import { OrderLookupService } from '../../application/services/OrderLookupService';
import { StockAllocationService } from '../../application/services/StockAllocationService';
import { CancelOrderUseCase } from '../../application/use-cases/CancelOrderUseCase';
import { DeliverOrderUseCase } from '../../application/use-cases/DeliverOrderUseCase';
import { GetOrderUseCase } from '../../application/use-cases/GetOrderUseCase';
import { GetProductStockUseCase } from '../../application/use-cases/GetProductStockUseCase';
import { ListOrdersUseCase } from '../../application/use-cases/ListOrdersUseCase';
import { ListProductStockUseCase } from '../../application/use-cases/ListProductStockUseCase';
import { PackOrderUseCase } from '../../application/use-cases/PackOrderUseCase';
import { PayOrderUseCase } from '../../application/use-cases/PayOrderUseCase';
import { PlaceOrderUseCase } from '../../application/use-cases/PlaceOrderUseCase';
import { ShipOrderUseCase } from '../../application/use-cases/ShipOrderUseCase';
import { StockReservationService } from '../../domain/inventory/StockReservationService';
import { OrderController } from '../http/controllers/OrderController';
import { StockController } from '../http/controllers/StockController';
import { Controllers } from '../http/createApp';
import { InMemoryOrderRepository } from '../persistence/InMemoryOrderRepository';
import { InMemoryProductRepository } from '../persistence/InMemoryProductRepository';
import { CryptoIdGenerator } from '../system/CryptoIdGenerator';
import { SystemClock } from '../system/SystemClock';
import { seedCatalogue } from './seedCatalogue';

/** Composition root: the single place where abstractions are bound to implementations. */
export function buildControllers(): Controllers {
  const products = new InMemoryProductRepository();
  const orders = new InMemoryOrderRepository();
  seedCatalogue(products);

  const clock = new SystemClock();
  const ids = new CryptoIdGenerator();
  const reservation = new StockReservationService();
  const allocations = new StockAllocationService(products);
  const lookup = new OrderLookupService(orders);

  const orderController = new OrderController({
    placeOrder: new PlaceOrderUseCase(orders, allocations, reservation, ids, clock),
    getOrder: new GetOrderUseCase(lookup),
    listOrders: new ListOrdersUseCase(orders),
    payOrder: new PayOrderUseCase(lookup, orders, clock),
    packOrder: new PackOrderUseCase(lookup, orders, clock),
    shipOrder: new ShipOrderUseCase(lookup, orders, allocations, reservation, clock),
    deliverOrder: new DeliverOrderUseCase(lookup, orders, clock),
    cancelOrder: new CancelOrderUseCase(lookup, orders, allocations, reservation, clock),
  });
  const stockController = new StockController(
    new ListProductStockUseCase(products),
    new GetProductStockUseCase(products),
  );

  return { orders: orderController, stock: stockController };
}

