import { Product } from '../../domain/product/Product';
import { ProductRepository } from '../../domain/product/ProductRepository';
import { Money } from '../../domain/shared/Money';

const CATALOGUE = [
  { id: 'SKU-KEYBOARD', name: 'Mechanical keyboard', unitPriceCents: 8999, initialStock: 25 },
  { id: 'SKU-MOUSE', name: 'Wireless mouse', unitPriceCents: 2999, initialStock: 50 },
  { id: 'SKU-MONITOR', name: '27" monitor', unitPriceCents: 24999, initialStock: 10 },
  { id: 'SKU-CABLE', name: 'USB-C cable', unitPriceCents: 999, initialStock: 200 },
] as const;

export function seedCatalogue(products: ProductRepository): void {
  for (const item of CATALOGUE) {
    products.save(
      Product.create({
        id: item.id,
        name: item.name,
        unitPrice: Money.ofCents(item.unitPriceCents),
        initialStock: item.initialStock,
      }),
    );
  }
}

